#!/usr/bin/env node
/* ============================================================
   TMUA Lab — single-file build.  `node tools/bundle.js`
   Inlines every stylesheet, script and page body into one
   self-contained HTML document with hash routing, ready to
   publish as an Artifact. The multi-page site stays the source
   of truth; nothing here is hand-maintained.
   ============================================================ */
'use strict';
const fs = require('fs');
const path = require('path');
const ROOT = path.join(__dirname, '..');
const read = p => fs.readFileSync(path.join(ROOT, p), 'utf8');

/* ---------- pages ---------- */

const PAGES = [
  ['index.html', 'home'], ['practice.html', 'practice'], ['mock.html', 'mock'],
  ['review.html', 'review'], ['progress.html', 'progress'], ['questions.html', 'questions'],
  ['guide.html', 'guide'], ['community.html', 'community'],
  ['privacy.html', 'privacy'], ['terms.html', 'terms']
];
const ROUTE = { 'index.html': '#/' };
PAGES.forEach(([f, n]) => { if (f !== 'index.html') ROUTE[f] = '#/' + n; });

const FILES = Object.keys(ROUTE).map(f => f.replace('.html', '')).join('|');

/** Rewrite every cross-page link into its hash route. */
function relink(src) {
  return src
    .replace(new RegExp('(' + FILES + ')\\.html#report', 'g'), (_, f) => ROUTE[f + '.html'] + '?to=report')
    .replace(new RegExp('(' + FILES + ')\\.html', 'g'), (_, f) => ROUTE[f + '.html']);
}

/* ---------- styles ---------- */

let css = ['tokens', 'site', 'app'].map(n => read(`assets/css/${n}.css`)).join('\n\n');

// the prose/contents styles live in the head of the long-form pages
const extra = new Set();
for (const [file] of PAGES) {
  const m = read(file).match(/<style>\n([\s\S]*?)<\/style>/);
  if (m) extra.add(m[1].trim());
}
css += '\n\n/* ---------- long-form pages ---------- */\n\n' + [...extra].join('\n\n');

/* ---------- views ---------- */

const VIEWS = {};
for (const [file, name] of PAGES) {
  const html = read(file);
  const m = html.match(/<main id="main">([\s\S]*?)<\/main>/);
  if (!m) throw new Error('no <main id="main"> in ' + file);
  VIEWS[name] = relink(m[1]).trim();
}

/* ---------- scripts ---------- */

const CORE = ['math', 'bank-past', 'bank-p1', 'bank-p2', 'core', 'shell', 'session'];
const PAGE_JS = [
  ['home', 'home'], ['practice', 'practice'], ['mock', 'mock'], ['review', 'review'],
  ['progress', 'progress'], ['questions', 'questions'], ['community', 'community']
];

function shared(name) {
  let src = relink(read(`assets/js/${name}.js`));
  if (name === 'shell') {
    // the router owns navigation, page identity and boot in this build
    src = src.replace(
      /    var f = root\.location\.pathname\.split\('\/'\)\.pop\(\);\n    return f \|\| '#\/';/,
      "    var h = (root.location.hash || '').replace(/^#\\/?/, '').split('?')[0];\n    return '#/' + h;"
    );
    src = src.replace(/root\.location\.href = it\.href;/g, 'TL.go(it.href);');
    src = src.replace(
      /  if \(D\.readyState === 'loading'\) D\.addEventListener\('DOMContentLoaded', boot\);\n  else boot\(\);/,
      '  TL.bootShell = boot;   // the router calls the pieces it needs'
    );
  }
  return src;
}

function pageScript(name, route) {
  let src = relink(read(`assets/js/${name}.js`));
  src = src.replace(/\bTL\.page = /g, `TL.pages.${route} = `);
  src = src.replace(/root\.location\.href = ([^;]+);/g, 'TL.go($1);');
  return src;
}

const js = [
  '/* TMUA Lab — generated by tools/bundle.js. Edit the sources, not this file. */',
  'window.TL = window.TL || {}; window.TL.pages = {};',
  ...CORE.map(shared),
  ...PAGE_JS.map(([f, r]) => pageScript(f, r)),
  'window.TL.VIEWS = ' + JSON.stringify(VIEWS) + ';',
  read('assets/js/artifact.js')
].join('\n\n');

/* ---------- document ---------- */

const out = `<title>TMUA Lab</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&family=IBM+Plex+Sans:ital,wght@0,400;0,500;0,600;1,400&family=IBM+Plex+Mono:wght@400;500&family=IBM+Plex+Serif:ital,wght@0,400;0,500;1,400&display=swap" rel="stylesheet">
<style>
${css}
</style>

<a class="skip" href="#main">Skip to content</a>
<header id="hdr"></header>
<main id="main"></main>
<footer id="ftr"></footer>

<script>
${js}
</script>
`;

fs.mkdirSync(path.join(ROOT, 'dist'), { recursive: true });
const dest = path.join(ROOT, 'dist', 'tmualab.html');
fs.writeFileSync(dest, out);

const kb = n => (n / 1024).toFixed(1) + ' KB';
console.log('dist/tmualab.html   ' + kb(out.length));
console.log('  css   ' + kb(css.length));
console.log('  js    ' + kb(js.length));
console.log('  views ' + Object.keys(VIEWS).map(k => k + ' ' + kb(VIEWS[k].length)).join(', '));

// guardrails
const leftovers = out.match(new RegExp('(' + FILES + ')\\.html', 'g'));
if (leftovers) { console.error('\nUNRESOLVED LINKS: ' + [...new Set(leftovers)].join(', ')); process.exit(1); }
if (/TL\.page\s*=[^=]/.test(js)) { console.error('\nA page script still assigns TL.page'); process.exit(1); }
console.log('\nno unresolved page links');
